const { accessSync, constants } = await import('node:fs');
const input = process.env.IMAGE_PATH;
if (!input) throw new Error('Missing IMAGE_PATH');
try { accessSync(input, constants.R_OK); } catch { throw new Error('Input image not accessible'); }
globalThis.inputPath = input;
globalThis.outputPath = '/tmp/output.pdf';

const { execFileSync } = await import('node:child_process');
const img2pdfPath = require.resolve('img2pdf/bin/img2pdf.js');
execFileSync('node', [img2pdfPath, globalThis.inputPath, '-o', globalThis.outputPath]);
